fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x181028);
    let far: i32 = (t / 4) % 120;
    let mut i: i32 = 0 - 1;
    while i < w / 120 + 1 {
        let x: i32 = i * 120 - far;
        host::display::fill_triangle(x, h - 60, x + 60, h - 130, x + 120, h - 60, 0x302848);
        i = i + 1;
    }
    let mid: i32 = (t / 2) % 90;
    i = 0 - 1;
    while i < w / 90 + 1 {
        let x: i32 = i * 90 - mid;
        host::display::fill_rect(x + 20, h - 90, 34, 30, 0x504070);
        i = i + 1;
    }
    host::display::fill_rect(0, h - 60, w, 60, 0x282038);
    let near: i32 = (t * 2) % 48;
    i = 0 - 1;
    while i < w / 48 + 1 {
        host::display::fill_rect(i * 48 - near, h - 30, 24, 4, 0x8070a0);
        i = i + 1;
    }
    host::display::present();
}
